-- Select constant value
SELECT 42 AS answer;

-- Compute scalar expression
SELECT 100 + 5 AS total_sum;

-- Query current timestamp
SELECT CURRENT_DATE;

-- Select single column
SELECT title FROM books;

-- Select multiple columns with aliases
SELECT first_name AS given_name, email AS contact_email
FROM members;

-- Equality filter
SELECT name FROM users WHERE is_active = true;

-- Range filter with AND
SELECT id, score FROM exam_results
WHERE score >= 75 AND score <= 90;

-- String comparison
SELECT id, title FROM courses WHERE category = 'Backend';

-- Checking for missing values
SELECT id, customer_name FROM orders
WHERE delivered_at IS NULL;

-- Checking for present values
SELECT id FROM users WHERE phone IS NOT NULL;

-- Fallback default with COALESCE
SELECT id, COALESCE(nickname, username, 'Anonymous') AS display_name
FROM profiles;

-- Sort ascending (default)
SELECT name, score FROM leaderboard ORDER BY score ASC;

-- Sort descending with limit (top 3)
SELECT name, salary FROM employees
ORDER BY salary DESC
LIMIT 3;

-- Multi-column tie breaking
SELECT name, department, salary FROM employees
ORDER BY department ASC, salary DESC;

